        grant("g-1", "subj-http", Purpose.RESEARCH);
        writeRecord("w-1", "subj-http", Purpose.RESEARCH, "rec-1", "epoch1");
        adjust("q-1", "subj-http", Purpose.RESEARCH, 1, 10L);
